s=mk(331,'Science, Technology and Society: Hot and Cold Packs','سائنس، ٹیکنالوجی اور معاشرہ: گرم اور ٹھنڈے پیک','ساینس، ټیکنالوجي او ټولنه: ګرمې او یخې کڅوړې','hot-cold-packs')
F=[]
add(s,'h','Science, Technology and Society','سائنس، ٹیکنالوجی اور معاشرہ','ساینس، ټیکنالوجي او ټولنه',kind='heading')
add(s,'a1',"Heat changes occur when a solute is dissolved in solvent. 'Hot and Cold Packs' use this property. These packs are used by patients to treat their muscle strain and sore joints and to reduce swellings in body muscles.",'حرارتی تبدیلیاں اس وقت ہوتی ہیں جب محلول شدہ شے محلل میں حل ہوتی ہے۔ "گرم اور ٹھنڈے پیک" اس خاصیت کو استعمال کرتے ہیں۔ یہ پیک مریض اپنے پٹھوں کے کھنچاؤ اور جوڑوں کے درد کے علاج اور جسمانی پٹھوں میں سوجن کم کرنے کے لیے استعمال کرتے ہیں۔','د تودوخې بدلونونه هغه مهال پېښېږي کله چې محلول شوی مواد په محلل کې حل شي. "ګرمې او یخې کڅوړې" دا ځانګړنه کاروي. دا کڅوړې ناروغان د خپلو عضلاتو د کش کېدو او د مفصلونو د درد د درملنې او د بدن په عضلاتو کې د پړسوب د کمولو لپاره کاروي.')
add(s,'a2','These packs contain solute and the solvent in separate bags inside the pack. At the time of use, the pack is squeezed and the solvent bag is broken. Solvent reacts with solute and the temperature effect is utilized by the patient.','ان پیکوں میں محلول شدہ شے اور محلل پیک کے اندر الگ الگ تھیلوں میں ہوتے ہیں۔ استعمال کے وقت پیک کو دبایا جاتا ہے اور محلل کا تھیلا ٹوٹ جاتا ہے۔ محلل محلول شدہ شے کے ساتھ تعامل کرتا ہے اور درجہ حرارت کے اثر سے مریض فائدہ اٹھاتا ہے۔','دا کڅوړې محلول شوی مواد او محلل په کڅوړې دننه په جلا کڅوړو کې لري. د کارولو په وخت کڅوړه ټینګېږي او د محلل کڅوړه ماتېږي. محلل له محلول شوي مواد سره تعامل کوي او د تودوخې اغېز ناروغ کاروي.')
add(s,'a3','Mostly, the hot packs use calcium chloride, which produce heat when dissolved in water as below','زیادہ تر گرم پیک کیلشیم کلورائیڈ استعمال کرتے ہیں جو پانی میں حل ہونے پر درج ذیل کے مطابق حرارت پیدا کرتا ہے','ډېری ګرمې کڅوړې کلسیم کلوراید کاروي چې په اوبو کې د حل کېدو پر مهال لاندې ډول تودوخه جوړوي')
add(s,'a4','The molar heat of solution of CaCl₂ is 82.8kJ mol⁻¹ and it is an exothermic reaction.','CaCl₂ کی مولر حرارتِ محلول 82.8kJ mol⁻¹ ہے اور یہ حرارت خارج کرنے والا تعامل ہے۔','د CaCl₂ مولر د محلول تودوخه 82.8kJ mol⁻¹ ده او دا یو تودوخه خوشې کوونکی تعامل دی.')
add(s,'a5','The cold packs utilize ammonium nitrate (NH₄NO₃) which absorbs heat from surrounding when it is dissolved in water','ٹھنڈے پیک امونیم نائٹریٹ (NH₄NO₃) استعمال کرتے ہیں جو پانی میں حل ہونے پر ماحول سے حرارت جذب کرتا ہے','یخې کڅوړې امونیم نایټریټ (NH₄NO₃) کاروي چې کله په اوبو کې حل شي له شاوخوا څخه تودوخه جذبوي')
add(s,'a6','It is an endothermic reaction and reduce the pain by cooling effect.','یہ حرارت جذب کرنے والا تعامل ہے اور ٹھنڈک کے اثر سے درد کم کرتا ہے۔','دا یو تودوخه جذبوونکی تعامل دی او د یخولو اغېز په واسطه درد کموي.')
s['equations']=[eqn(331,'cacl2',r'\mathrm{CaCl_{2(s)}\longrightarrow Ca^{2+}_{(aq)}+2Cl^-_{(aq)}}\qquad\Delta H=-82.8\ \mathrm{kJ\,mol^{-1}}','CaCl₂(s) → Ca²⁺(aq) + 2Cl⁻(aq)   ΔH = −82.8 kJ mol⁻¹'),eqn(331,'nh4no3',r'\mathrm{NH_4NO_{3(s)}\longrightarrow NH^+_{4(aq)}+NO^-_{3(aq)}}\qquad\Delta H=+25.7\ \mathrm{kJ\,mol^{-1}}','NH₄NO₃(s) → NH₄⁺(aq) + NO₃⁻(aq)   ΔH = +25.7 kJ mol⁻¹')]
P=lambda *k:dict(type='paragraphs',ids=[f'chem11-p331-{x}' for x in k])
